-- Competition-adjacent VideoQA literature map, reviewed from primary papers.
-- The views separate broad research threads, team-to-literature interpretation,
-- and the deeper paper inventory used by the progressive-disclosure report.

CREATE OR REPLACE VIEW research_threads AS
SELECT *
FROM (VALUES
  (1,'Allocate the visual-token budget','Guarantee broad coverage, then spend remaining frames on question relevance and scene diversity instead of only increasing frame count.','NII_UIT; CERTH-ITI','At the same 12/24/32-frame budgets, compare uniform, random-view, query-only, and uniform-plus-query selection; score evidence recall and answer quality.'),
  (2,'Separate retrieval from fusion','Treat finding the required moments and reasoning over already-found moments as different failure modes.','NII_UIT; HLTCOE','Annotate required frames for a small development slice; report selector recall, oracle-frame answer accuracy, and end-to-end accuracy.'),
  (3,'Combine global chronology with local detail','Use low-cost panels or global frames for the timeline, then preserve native-resolution crops around selected moments.','NII_UIT','Compare full frames, panels, tiles, and global-plus-selective-tiles under the same visual-token budget; stratify OCR/small-object questions.'),
  (4,'Keep native audio and ASR complementary','Use transcripts for speech and native audio for sound events, timing, tone, music, and cues lost by transcription.','CERTH-ITI; NII_UIT; HLTCOE','Run matched video-only, +ASR, +native-audio, and +both ablations with timestamps and per-question modality labels.'),
  (5,'Ground multi-evidence and causal reasoning','Retrieve separated cues and build a short, inspectable cause-to-effect chain rather than relying on unverified chain-of-thought.','All teams','Store timestamps and frame IDs for every answer candidate; score evidence recall separately from answer correctness on a manually grounded development slice.'),
  (6,'Separate generation, election, and calibration','Generate diverse candidates or view-level scores, then elect with evidence consistency, probability pooling, listwise ranking, and MC option-bias calibration.','CERTH-ITI; HLTCOE; WHU-NERCMS; kslab','MC: pool option scores across permutations. AG: semantic deduplication plus evidence-aware reranking; report top-1, oracle-at-k, official top-10, and cost.')
) AS t(priority, thread, field_direction, closest_2025_teams, recommended_2026_test);

CREATE OR REPLACE VIEW research_concept_guide AS
SELECT *
FROM (VALUES
  (1,'Visual-token budget','Choose which moments earn space in the model''s limited input. “Token” here means model context, not cryptocurrency.','Did the system see every part of the clip and also the moments most related to the question?','Selected frame IDs, timestamps, selector scores, frame count, and total visual tokens.','At one fixed budget, compare uniform-only, question-only, and a half-uniform plus half-question sampler.'),
  (2,'Retrieval versus fusion','Retrieval finds the necessary moments; fusion combines facts across those moments. A system can succeed at one and fail at the other.','If given the correct frames by an oracle, can the model answer? If yes, selection—not reasoning—is the main problem.','Required-frame labels, retrieved-frame recall, oracle-frame answer, and end-to-end answer.','Hand-label required moments for 50–100 development questions, then measure selector recall and oracle accuracy separately.'),
  (3,'Global chronology plus local detail','Keep a cheap view of the whole timeline, then zoom into a few moments for text, faces, hands, or small objects.','Did compression preserve event order, and did the zoomed evidence retain the detail needed to answer?','Global frame times, chosen crop boxes, crop resolution, OCR text, and the question type.','Compare global frames, panels, all-frame tiles, and global frames plus selective tiles at equal visual tokens.'),
  (4,'ASR plus native audio','Automatic speech recognition turns words into searchable text; native audio preserves alarms, music, tone, timing, and other sounds that transcripts omit.','Would the answer change if the words were correct but the non-speech sound track were removed?','Timestamped transcript spans, ASR confidence, audio-event timestamps, and modality-ablation results.','Run video-only, video plus transcript, video plus native audio, and video plus both on the same questions.'),
  (5,'Grounded causal reasoning','Connect cause, intermediate event, and outcome to inspectable timestamps instead of accepting a plausible verbal explanation.','Can every important clause in the answer point to a frame, crop, transcript span, or sound event?','Evidence IDs, timestamps, cause-to-effect order, answer correctness, and evidence recall.','Label short evidence chains for causal development questions and score both answer accuracy and chain coverage.'),
  (6,'Generation, election, and calibration','Generate several plausible outputs, elect the one best supported by evidence, and calibrate scores so confidence reflects reliability rather than wording or option position.','Does the winner remain stable across paraphrases, evidence views, and shuffled MC option order?','Candidate text, semantic cluster, cited evidence, option logits, confidence, election score, and final rank.','AG: deduplicate then evidence-rerank candidates. MC: shuffle options, map back, and pool direct option scores.')
) AS t(priority, idea, plain_meaning, diagnostic_question, evidence_to_store, first_experiment);

CREATE OR REPLACE VIEW team_literature_map AS
SELECT *
FROM (VALUES
  ('CERTH-ITI','Native audio plus visual-context sample scaling','Qwen2.5-Omni; VCSS; VPS; BOLD; RLER','Multiple complementary views and time-aligned audio are defensible test-time scaling tools; probability aggregation is stronger than treating every sample independently.','Random views may overlap; exact-string AG voting splits paraphrases; no explicit evidence localization/election; MC option bias is untested.','Under one total frame budget, compare random with disjoint bin-wise views. Semantic-deduplicate AG and rank by cited-evidence consistency; average MC logits across option permutations.'),
  ('NII_UIT','Evidence densification with frozen reasoners','Whisper; KFS-Bench; BOLT; Video Panels; TimeChat','Coverage, relevance, question routing, spatial detail, and timestamped transcripts can improve a frozen downstream model without expensive task tuning.','Fixed uniform frames may spend tiles on irrelevant moments; transcript-only audio loses non-speech cues; the precise external tiling recipe lacks direct TRECVID evidence.','Hold at 12 frames and compare uniform, balanced question-guided, and 6-uniform + 6-query selection. Tile only selected moments and report by question type.'),
  ('HLTCOE','Generate candidates, then learn a listwise ranker','Qwen2.5-VL; RADI; RLER','Generation and selection are separable, and partial-listwise training is appropriate when only one reference answer is labeled.','BERTScore-derived targets reward semantic similarity, not visual evidence; frame selection is undocumented; near-duplicate control is not a direct objective.','Keep the generator fixed. Require 2–3 cited timestamps per candidate and compare the current ranker with an evidence-aware, diversity-aware ranker.'),
  ('WHU-NERCMS','Direct VideoLLM plus post-hoc MC matching','QGAC-TR; BOLD','Simple direct systems remain useful baselines, but MC benefits from option-conditioned grounding and calibration.','A wrong free-text anchor propagates into cosine ranking; option-position bias, no-video shortcuts, and direct option likelihood were not controlled.','Compare anchor-cosine, direct option-letter logits, and one-vs-rest verification across option permutations, with no-video and question-only controls.'),
  ('kslab','Small LoRA model plus self-reward or embedding selection','VCSS; RLER; BOLD','Small adapted models can remain competitive when extra inference and answer election are disciplined.','Audio is omitted; mean token confidence can favor short answers; MC semantic-anchor ranking propagates anchor errors.','Add Whisper without changing the 2B backbone. Cross transcript on/off with majority vote, length-normalized confidence, and evidence-aware candidate election.'),
  ('tcna','Proprietary long-context ceiling baseline','LongVideoBench; Video-MME','Strong closed models are useful ceilings across duration and modality conditions.','Unpublished preprocessing and output construction make the pipeline irreproducible and hard to diagnose.','Freeze endpoint/date/upload settings; log processed evidence and five repeated calls; run video-only, transcript-only, full-audio, no-video, and option-permutation ablations with latency and cost.'),
  ('TJUMI','Broad VideoLLaMA2 fine-tuning','VideoLLaMA2 lineage; long-video evaluation practice','Fine-tuning may improve task fit only when the complete inference and submission path is controlled.','A submission bug and undocumented preprocessing, audio, ranking, and corrected results prevent attribution; data and backbone effects are confounded.','First add an automatic format/completeness validator. Then hold sampler, prompts, and output code fixed while comparing VideoLLaMA2 with one modern backbone.')
) AS t(team, research_lineage, primary_anchors, what_literature_supports, frontier_gap, experiment_2026);

CREATE OR REPLACE VIEW literature_review AS
SELECT *
FROM (VALUES
  (1,'5/5','Peer-reviewed','Causal + temporal benchmark','NExT-QA',2021,'Defines MC and open-ended QA for causal, temporal, and common-scene understanding; shows shallow description is much easier than explanation.','All teams','Tag development questions by reasoning type and report slices; MC success does not guarantee open-answer transfer.','https://arxiv.org/abs/2105.08276'),
  (2,'4/5','Peer-reviewed','Long-video benchmark','EgoSchema',2023,'Uses three-minute five-way MC clips and temporal certificate length to distinguish video duration from required evidence duration.','All teams','Allocate frames by evidence span, not clip length alone; remember that the benchmark is egocentric and MC-only.','https://arxiv.org/abs/2308.09126'),
  (3,'5/5','Peer-reviewed','Long-context benchmark','LongVideoBench',2024,'Tests retrieval plus reasoning over variable-length videos and subtitles up to one hour.','All teams','Use duration-aware frame budgets and test where evidence occurs; native audio and open answers remain outside its scope.','https://arxiv.org/abs/2407.15754'),
  (4,'5/5','Peer-reviewed','Duration + modality benchmark','Video-MME',2025,'Evaluates short, medium, and long videos under visual-only, subtitle, and audio settings.','CERTH-ITI; NII_UIT; HLTCOE','Copy its matched modality-ablation logic into local TRECVID tests; MC accuracy does not cover exact-10 AG.','https://arxiv.org/abs/2405.21075'),
  (5,'4/5','Peer-reviewed','Long-video benchmark','MLVU',2025,'Tests diverse genres and tasks; evaluated MLLMs degrade as videos become longer.','All teams','Validate across duration and genre slices instead of selecting one pipeline from an aggregate score.','https://arxiv.org/abs/2406.04264'),
  (6,'5/5','Peer-reviewed','Multi-evidence benchmark','HERBench',2026,'Requires at least three separated cues and distinguishes retrieval failures from fusion failures, including oracle-frame evaluation.','All teams','Create a small required-frame development set and score selector recall, oracle reasoning, and end-to-end performance separately.','https://arxiv.org/abs/2512.14870'),
  (7,'4/5','Peer-reviewed','Grounded causal benchmark','CaST-Bench',2026,'Requires timestamped and spatially grounded cause-to-effect evidence chains as well as the final answer.','All teams','Use timestamped evidence chains as an internal diagnostic; bounding-box supervision may be excessive for the official task.','https://arxiv.org/abs/2605.23216'),
  (8,'5/5','Peer-reviewed','Open-ended multimodal benchmark','MovieRecapsQA',2026,'Uses expected answer facts, modality labels, dialogue, and reference-free factual evaluation for open-ended movie QA.','All AG teams','Track required-fact coverage and factuality beside official similarity metrics; movie narration is a domain caveat.','https://arxiv.org/abs/2601.02536'),
  (9,'4/5','Peer-reviewed','Agentic temporal search','VideoAgent',2024,'An LLM iteratively plans which visual information to retrieve with tools and uses few frames on average.','NII_UIT lineage','Try coarse scan then bounded zoom-in calls; audit latency, error propagation, and missing audio.','https://arxiv.org/abs/2403.10517'),
  (10,'4/5','Peer-reviewed','Hierarchical temporal search','VideoTree',2025,'Builds a training-free query-adaptive coarse-to-fine tree over long-video summaries.','NII_UIT; CERTH-ITI','Represent clips as chapters/events and inspect relevant branches at higher resolution; caption errors can erase fine evidence.','https://arxiv.org/abs/2405.19209'),
  (11,'5/5','Peer-reviewed','Training-free frame selection','BOLT',2025,'Samples frames from a query-relevance distribution instead of taking only uniform or deterministic top-k frames.','NII_UIT; CERTH-ITI','Use as a low-risk selector baseline, but retain coverage because similarity can discard causal setup frames.','https://arxiv.org/abs/2503.21483'),
  (12,'5/5','Peer-reviewed','Frame-selection evaluation','KFS-Bench',2026,'Annotates multiple disjoint required scenes and finds that coverage and balance matter beyond precision.','NII_UIT; CERTH-ITI','Start with a union of uniform and query-selected frames; its metrics require evidence annotations.','https://arxiv.org/abs/2512.14017'),
  (13,'4/5','Peer-reviewed','Temporal panels','Video Panels',2026,'Packs multiple moments into panels, trading per-frame spatial detail for broader temporal coverage without training.','NII_UIT lineage','Compare panels with separate frames at equal tokens; keep high-resolution selected frames for text and small objects.','https://arxiv.org/abs/2509.23724'),
  (14,'4/5','Peer-reviewed','Learned frame selection','Efficient Frame Selection via RL',2026,'Optimizes a lightweight selector with frame- and combination-level answer utility after relevance pretraining.','NII_UIT lineage','Train only after a training-free selector wins; MC reward and backbone coupling may not transfer to AG.','https://openaccess.thecvf.com/content/CVPR2026/html/Qin_Efficient_Frame_Selection_for_Long_Video_Understanding_via_Reinforcement_Learning_CVPR_2026_paper.html'),
  (15,'4/5','Peer-reviewed','Timestamp-aware modeling','TimeChat',2024,'Preserves time through a timestamp-aware frame encoder and sliding video Q-Former for long-video grounding.','NII_UIT; HLTCOE','Retain timestamp identity through preprocessing rather than presenting frames as an unordered gallery.','https://arxiv.org/abs/2312.02051'),
  (16,'5/5 MC','Peer-reviewed','Option-guided grounding','QGAC-TR',2024,'Uses question and option texts to guide and calibrate temporal localization without temporal labels.','WHU-NERCMS; CERTH-ITI; NII_UIT','Score evidence separately for each MC option instead of generating one free-text anchor.','https://aclanthology.org/2024.findings-emnlp.176/'),
  (17,'5/5','Peer-reviewed','Confidence-guided localization','FALCONEye',2026,'Searches hour-long video with calibrated answer confidence and returns an open answer plus a supporting temporal window.','NII_UIT; HLTCOE','Use bounded coarse-to-fine search and preserve the selected window as AG provenance; repeated calls add cost.','https://arxiv.org/abs/2503.19850'),
  (18,'4/5','Official technical report','Dynamic resolution + time','Qwen2.5-VL',2025,'Supports native dynamic resolution and absolute-time video encoding in the backbone used by HLTCOE.','HLTCOE','Preserve native aspect ratio, resolution, and timestamps; backbone capability does not validate a competition pipeline.','https://arxiv.org/abs/2502.13923'),
  (19,'5/5 CERTH','Official technical report','Native audio-video model','Qwen2.5-Omni',2025,'Time-aligns raw audio and video in the native multimodal backbone used by CERTH-ITI.','CERTH-ITI','Compare native audio with transcript-only and combined inputs; the speech-generating Talker is irrelevant.','https://arxiv.org/abs/2503.20215'),
  (20,'3/5','Peer-reviewed','Speech transcription','Whisper',2023,'Provides strong zero-shot ASR and timestamps from large-scale weak supervision.','NII_UIT; HLTCOE','Keep timestamped transcripts, but audit ASR error and preserve a native-audio path for non-speech cues.','https://proceedings.mlr.press/v202/radford23a.html'),
  (21,'5/5','Peer-reviewed','Visual-context sample scaling','VCSS',2025,'Combines multiple bin-wise frame samples using frequency, marginal confidence, and question-specific reasoning scores.','CERTH-ITI; kslab','Replace unconstrained overlapping views with complementary bins and richer election; confirm the transfer with a controlled local ablation.','https://arxiv.org/abs/2503.20472'),
  (22,'5/5','Peer-reviewed','Parallel multi-view scaling','Video Parallel Scaling',2026,'Runs diverse frame subsets in parallel and aggregates output probabilities rather than only answer strings.','CERTH-ITI','Test disjoint views and probability pooling; open-ended token-sequence aggregation is harder than MC logits.','https://arxiv.org/abs/2509.08016'),
  (23,'5/5 MC','Peer-reviewed','MC selection-bias calibration','BOLD / Addressing Blind Guessing',2025,'Finds option-position bias in video-language MCQA and proposes inference-time calibration.','All MC teams','Test option permutations and no-video controls before trusting option-letter scores; calibration cannot repair missing evidence.','https://aclanthology.org/2025.acl-long.162/'),
  (24,'4/5','Peer-reviewed','Open-answer listwise ranking','RADI',2024,'Transfers answer order with robust pairwise and partial-listwise objectives under incomplete VideoQA labels.','HLTCOE; kslab','Supports learning a ranker from one reference, but fixed answer vocabularies differ from generative TRECVID AG.','https://arxiv.org/abs/2403.14430'),
  (25,'5/5','Peer-reviewed','Evidence-aware candidate election','RLER',2026,'Generates a small answer set and elects using evidence consistency, confidence, transparency, and non-redundancy.','HLTCOE; CERTH-ITI; kslab','Require AG candidates to cite frames/timestamps and rerank on evidence consistency; generated rationales still need faithfulness checks.','https://arxiv.org/abs/2604.04379')
) AS t(read_order, proximity, evidence_status, thread, work, year, contribution, closest_2025_teams, competition_takeaway, primary_url);
